// Port of the delete/compaction half of gas/test/ledgerFlow.test.ts, reshaped for the
// three-scope code register, plus the scope behaviour gas/ has no golden for.
//
// Two populations of test live here and it matters which is which:
//
//   FIXTURE PARITY — test/fixtures/ledger_flow.json's `delete_result` / `after_delete_scan2`
//   steps and the whole of test/fixtures/ledger_compaction.json are BYTE COPIES from gas/,
//   generated by the Python domain layer. They are never edited or regenerated here. D3's
//   ledgerCore.test.ts consumed `after_scan1..4` and named these two goldens as "sitting in
//   the fixtures directory" for the package that added maintenance.ts; this is that package.
//   Both fixtures are fed through the SAME RENAME SHIM D3 wrote (copied below rather than
//   imported, so neither test file can quietly change the other's oracle) — it maps gas/'s
//   column names onto sheetsDb.ts's and nothing else. The records, the scan ids and every
//   expected value go in verbatim.
//
//   HAND-WRITTEN — the scope behaviour: a delete that spans registers, the cross-scope
//   compaction floor, the sealed-scan refusal, the two column contracts (`toEpisodeRow` and
//   `compactionRow` against TAB_HEADERS), and the cutoffMs/isAfter boundary.
//
// THE FIXTURES ARE SINGLE-SCOPE (gas/ had one register), so every fixture row is shimmed to
// `sca`. The three-register behaviour has no golden and cannot have one — it is pinned by the
// hand-written cases, whose numbers are derived with the arithmetic written out in the test.

import { describe, expect, it } from "vitest";
import {
  baseRows,
  emptyState,
  persistFlatScan,
  scansAsc,
} from "../src/domain/ledgerCore";
import { selectSealCandidates } from "../src/domain/compaction";
import {
  CHECKPOINT_VERSION,
  LedgerRebuildError,
  RETENTION_MIN_DAYS,
  SealedScanError,
  compactLedgerCore,
  compactionRow,
  cutoffMs,
  deleteScansCore,
  isAfter,
  loadReplayPayloads,
  recordsFromPayload,
  settledEpisodeRows,
  toEpisodeRow,
  type Checkpoint,
} from "../src/domain/maintenance";
import { MIN_UNSEALED_FLAT_SCANS } from "../src/domain/config";
import type {
  LedgerRow,
  LedgerState,
  Observation,
  ScanRow,
} from "../src/domain/ledgerTypes";
import { TABS, TAB_HEADERS } from "../src/server/sheetsDb";
import { cmp, type Rec } from "../src/domain/util";
import { expectParity, fixture } from "./helpers";

// --------------------------------------------------------------------------- #
//  The rename shim — D3's, copied from test/ledgerCore.test.ts
// --------------------------------------------------------------------------- #

/** gas/ column -> gas_devsecops column, for LEDGER rows (= TAB_HEADERS[TABS.ledger]). */
const RENAMED: Record<string, string> = {
  vuln_key: "finding_key",
  cve: "identifier",
  asset_id: "repo_id",
  asset_name: "repo_name",
  cloud: "platform",
};

/** Ledger fields with no counterpart, listed rather than silently dropped. */
const UNMAPPED: Record<string, string> = {
  asset_type: "the asset is always a repository; REPOSITORY vs REPOSITORY_BRANCH is `branch`",
  subscription_name: "no cloud subscription on a repo; ownership is owner_project from projects[]",
  subscription_ext_id: "same — see owner_project / owner_path",
};

/** Ledger fields that pass through under their own name. */
const PASSTHROUGH = [
  "severity", "first_seen", "last_seen", "status", "resolved_at", "resolution_src",
  "reopened_count", "first_scan_id", "last_scan_id", "tags_json",
];

/** SCAN fields with no counterpart. Exactly one, and it is ledgerCore's own divergence. */
const UNMAPPED_SCAN: Record<string, string> = {
  shape: "no grouped shape here; ScanRow has no `shape` column and every scan is flat",
};

const PASSTHROUGH_SCAN = [
  "scan_id", "ts", "mode", "total", "new_count", "resolved_count", "reopened_count",
  "severities", "sealed",
];

/** The one column this register ADDS to the scan row. gas/ had one register. */
const ADDED_SCAN = ["scope"];

/**
 * EPISODE fields. `compaction_id` is not in either fixture — gas/'s own test strips it before
 * comparing, because it is storage-specific — so it is listed here as ADDED rather than as a
 * passthrough, alongside the two columns this register's EpisodeRow adds.
 */
const RENAMED_EPISODE: Record<string, string> = {
  vuln_key: "finding_key",
  cve: "identifier",
};

const PASSTHROUGH_EPISODE = [
  "severity", "first_seen", "resolved_at", "resolution_src", "reopened_count",
  "superseded_by_scan",
];

/** Result-shape fields, which carry no renames at all: CompactionResult / DeleteResult. */
const PASSTHROUGH_RESULT = [
  "no_op", "dry_run", "scans_sealed", "episodes_created", "observations_pruned",
  "archive_bytes_freed", "db_bytes_freed", "floor_scan_id", "floor_ts",
];
const PASSTHROUGH_DELETE_RESULT = ["deleted", "scans", "tracked"];
const PASSTHROUGH_CHECKPOINT = ["version", "floor_scan_id", "floor_ts", "ledger"];

/** gas/'s `id:A` key becomes this register's scope-prefixed `sca:id:A` (lifecycle.findingKey). */
const renameKey = (k: string): string => `sca:${k}`;

function shimRow(row: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = { scope: "sca" };
  for (const [k, v] of Object.entries(row)) {
    if (k in UNMAPPED) continue;
    out[RENAMED[k] ?? k] = k === "vuln_key" ? renameKey(String(v)) : v;
  }
  return out;
}

function shimLedger(ledger: Record<string, any>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, row] of Object.entries(ledger)) out[renameKey(k)] = shimRow(row);
  return out;
}

function shimScans(scans: Record<string, unknown>[]): Record<string, unknown>[] {
  return scans.map((r) => {
    const out: Record<string, unknown> = { scope: "sca" };
    for (const [k, v] of Object.entries(r)) {
      if (k in UNMAPPED_SCAN) continue;
      out[k] = v;
    }
    return out;
  });
}

function shimObservations(obs: any[]): unknown[] {
  return obs.map((o) => ({
    scan_id: o.scan_id,
    finding_key: renameKey(o.vuln_key),
    present: o.present,
    severity: o.severity,
    status: o.status,
  }));
}

function shimEpisodes(eps: any[]): unknown[] {
  return eps.map((e) => {
    const out: Record<string, unknown> = { scope: "sca" };
    for (const [k, v] of Object.entries(e)) {
      out[RENAMED_EPISODE[k] ?? k] = k === "vuln_key" ? renameKey(String(v)) : v;
    }
    return out;
  });
}

function obsTable(observationsByScan: Record<string, Observation[]>): Observation[] {
  const all = Object.values(observationsByScan).flat();
  return [...all].sort(
    (a, b) => cmp(a.scan_id, b.scan_id) || cmp(a.finding_key, b.finding_key),
  );
}

/**
 * The archive envelope a PayloadReader hands back. Deliberately NOT gas/'s
 * `vulnerabilityFindings` key — that connection does not exist in this register, and
 * `recordsFromPayload` drops gas/'s special case for it in favour of the generic "first key
 * under `data` carrying `nodes`" walk. Naming a real code connection here is what exercises
 * that.
 */
function envelope(records: unknown[]) {
  return { data: { libraryVulnerabilities: { nodes: records } } };
}

/** Episodes as they compare: without the storage-specific compaction_id. */
function episodesWithoutId(episodes: Record<string, unknown>[]): Record<string, unknown>[] {
  return episodes.map(({ compaction_id, ...rest }) => rest);
}

// --------------------------------------------------------------------------- #
//  Fixture field accounting — every field renamed, passed through, or listed unmapped
// --------------------------------------------------------------------------- #

describe("fixture field accounting — nothing is silently dropped", () => {
  const flow = fixture("ledger_flow");
  const comp = fixture("ledger_compaction");

  function fieldsOf(rows: Iterable<Record<string, unknown>>): Set<string> {
    const out = new Set<string>();
    for (const r of rows) for (const k of Object.keys(r)) out.add(k);
    return out;
  }

  it("ledger_flow's delete steps carry only fields this file accounts for", () => {
    // `delete_result` is the DeleteResult shape; `after_delete_scan2` is a table step whose
    // ledger/scan/observation fields are D3's 18/10/5.
    expect(Object.keys(flow.steps.delete_result).sort()).toEqual(
      [...PASSTHROUGH_DELETE_RESULT].sort(),
    );
    const step = flow.steps.after_delete_scan2;
    expect(Object.keys(step).sort()).toEqual(
      ["episodes", "ledger", "observations", "scans"],
    );
    const ledgerFields = fieldsOf(Object.values(step.ledger));
    const accounted = new Set([
      ...Object.keys(RENAMED), ...Object.keys(UNMAPPED), ...PASSTHROUGH,
    ]);
    expect([...ledgerFields].filter((f) => !accounted.has(f)).sort()).toEqual([]);
    expect(ledgerFields.size).toBe(18); // 5 renamed + 3 unmapped + 10 passed through

    const scanFields = fieldsOf(step.scans);
    const scanAccounted = new Set([...Object.keys(UNMAPPED_SCAN), ...PASSTHROUGH_SCAN]);
    expect([...scanFields].filter((f) => !scanAccounted.has(f)).sort()).toEqual([]);
    expect(scanFields.size).toBe(10);
    expect(ADDED_SCAN.every((c) => !scanFields.has(c))).toBe(true);

    expect([...fieldsOf(step.observations)].sort()).toEqual(
      ["present", "scan_id", "severity", "status", "vuln_key"],
    );
    expect(step.episodes).toEqual([]);
  });

  it("ledger_compaction's top level is `now`, `retention_days`, `scans`, `expected`", () => {
    expect(Object.keys(comp).sort()).toEqual(["expected", "now", "retention_days", "scans"]);
    expect(Object.keys(comp.expected).sort()).toEqual([
      "after_compact", "after_delete_s3", "checkpoint", "delete_s3_result", "dry_run",
      "real", "sealed_delete_error",
    ]);
    expect(comp.retention_days).toBe(30);
  });

  it("every RESULT field the fixture carries is a CompactionResult / DeleteResult field", () => {
    // dry_run carries all nine; the real run's golden omits the two byte counters, which is
    // why the parity assertion below filters them off the actual side too.
    expect(Object.keys(comp.expected.dry_run).sort()).toEqual([...PASSTHROUGH_RESULT].sort());
    const real = new Set(Object.keys(comp.expected.real));
    expect([...real].filter((f) => !PASSTHROUGH_RESULT.includes(f)).sort()).toEqual([]);
    expect([...PASSTHROUGH_RESULT].filter((f) => !real.has(f)).sort()).toEqual([
      "archive_bytes_freed", "db_bytes_freed",
    ]);
    expect(Object.keys(comp.expected.delete_s3_result).sort()).toEqual(
      [...PASSTHROUGH_DELETE_RESULT].sort(),
    );
    expect(typeof comp.expected.sealed_delete_error).toBe("string");
  });

  it("every LEDGER / SCAN / OBSERVATION / EPISODE / CHECKPOINT field is accounted for", () => {
    const steps = [comp.expected.after_compact, comp.expected.after_delete_s3];
    const ledgerAccounted = new Set([
      ...Object.keys(RENAMED), ...Object.keys(UNMAPPED), ...PASSTHROUGH,
    ]);
    const scanAccounted = new Set([...Object.keys(UNMAPPED_SCAN), ...PASSTHROUGH_SCAN]);
    const episodeAccounted = new Set([
      ...Object.keys(RENAMED_EPISODE), ...PASSTHROUGH_EPISODE,
    ]);

    for (const step of steps) {
      const lf = fieldsOf(Object.values(step.ledger));
      expect([...lf].filter((f) => !ledgerAccounted.has(f)).sort()).toEqual([]);
      expect(lf.size).toBe(18);

      const sf = fieldsOf(step.scans);
      expect([...sf].filter((f) => !scanAccounted.has(f)).sort()).toEqual([]);
      expect(sf.size).toBe(10);
      expect(ADDED_SCAN.every((c) => !sf.has(c))).toBe(true);

      expect([...fieldsOf(step.observations)].sort()).toEqual(
        ["present", "scan_id", "severity", "status", "vuln_key"],
      );

      const ef = fieldsOf(step.episodes);
      expect([...ef].filter((f) => !episodeAccounted.has(f)).sort()).toEqual([]);
      expect(ef.size).toBe(8); // 2 renamed + 6 passed through
      // The fixture cannot carry these three: gas/'s test strips compaction_id, and gas/ has
      // no `scope` and no `component` on an episode.
      for (const added of ["compaction_id", "scope", "component"]) {
        expect(ef.has(added)).toBe(false);
      }
    }

    expect(Object.keys(comp.expected.checkpoint).sort()).toEqual(
      [...PASSTHROUGH_CHECKPOINT].sort(),
    );
    const cf = fieldsOf(comp.expected.checkpoint.ledger);
    expect([...cf].filter((f) => !ledgerAccounted.has(f)).sort()).toEqual([]);
    expect(cf.size).toBe(18);
  });
});

// --------------------------------------------------------------------------- #
//  ledger_flow.json — persist x4 then delete s2
// --------------------------------------------------------------------------- #

describe("ledger flow delete (SQLite fixture parity, scope sca)", () => {
  const fx = fixture("ledger_flow");
  const ids = ["s1", "s2", "s3", "s4"] as const;

  it("persist x4 then delete s2 reproduces every table state", () => {
    const state = emptyState();
    const obsByScan: Record<string, Observation[]> = {};
    const stepNames = ["after_scan1", "after_scan2", "after_scan3", "after_scan4"];

    ids.forEach((key, i) => {
      const scan = fx.scans[key];
      const { observations } = persistFlatScan(state, scan.records, {
        scope: "sca",
        mode: "live",
        scanId: scan.id,
      });
      obsByScan[scan.id] = observations;
      const expected = fx.steps[stepNames[i]!];
      expectParity(scansAsc(state.scans), shimScans(expected.scans));
      expectParity(state.ledger, shimLedger(expected.ledger));
      expectParity(obsTable(obsByScan), shimObservations(expected.observations));
      expectParity(state.episodes, expected.episodes);
    });

    // Delete s2 -> replay survivors; identical to a ledger that never saw s2.
    const readPayload = (row: ScanRow) => {
      const key = ids.find((k) => fx.scans[k].id === row.scan_id)!;
      return envelope(fx.scans[key].records);
    };
    const del = deleteScansCore(state, [fx.scans.s2.id], readPayload, null);
    expectParity(del.result, fx.steps.delete_result);
    const expected = fx.steps.after_delete_scan2;
    expectParity(scansAsc(del.state.scans), shimScans(expected.scans));
    expectParity(del.state.ledger, shimLedger(expected.ledger));
    expectParity(obsTable(del.observationsByScan), shimObservations(expected.observations));
    expectParity(del.state.episodes, expected.episodes);

    // The input state is not mutated — the caller decides whether to apply the rebuild.
    expect(state.scans.length).toBe(4);
    expect(Object.keys(state.ledger).sort()).toEqual(
      ["sca:id:A", "sca:id:B", "sca:id:C", "sca:id:D", "sca:id:E"],
    );
  });

  it("every replayed scan row keeps its scope", () => {
    const state = emptyState();
    for (const key of ids) {
      persistFlatScan(state, fx.scans[key].records, {
        scope: "sca", mode: "live", scanId: fx.scans[key].id,
      });
    }
    const readPayload = (row: ScanRow) =>
      envelope(fx.scans[ids.find((k) => fx.scans[k].id === row.scan_id)!].records);
    const del = deleteScansCore(state, [fx.scans.s2.id], readPayload, null);
    expect(del.state.scans.map((r) => r.scope)).toEqual(["sca", "sca", "sca"]);
    for (const row of Object.values(del.state.ledger)) {
      expect(row.scope).toBe("sca");
      expect(row.finding_key.startsWith("sca:")).toBe(true);
    }
  });

  it("deleting an unknown scan id is a no-op that returns the state unchanged", () => {
    const state = emptyState();
    persistFlatScan(state, fx.scans.s1.records, {
      scope: "sca", mode: "live", scanId: fx.scans.s1.id,
    });
    const never = () => {
      throw new Error("readPayload must not be called for a no-op delete");
    };
    for (const ids2 of [[], ["no-such-scan"]]) {
      const del = deleteScansCore(state, ids2, never, null);
      expect(del.result).toEqual({ deleted: 0, scans: 0, tracked: 0 });
      expect(del.state).toBe(state);
      expect(del.observationsByScan).toEqual({});
    }
  });

  it("a survivor with an unreadable archive refuses BEFORE any state change", () => {
    const state = emptyState();
    for (const key of ids) {
      persistFlatScan(state, fx.scans[key].records, {
        scope: "sca", mode: "live", scanId: fx.scans[key].id,
      });
    }
    const before = JSON.stringify(state);
    const readPayload = (row: ScanRow) =>
      row.scan_id === fx.scans.s3.id
        ? null
        : envelope(fx.scans[ids.find((k) => fx.scans[k].id === row.scan_id)!].records);
    expect(() => deleteScansCore(state, [fx.scans.s2.id], readPayload, null)).toThrow(
      LedgerRebuildError,
    );
    expect(() => deleteScansCore(state, [fx.scans.s2.id], readPayload, null)).toThrow(
      new RegExp(fx.scans.s3.id),
    );
    expect(JSON.stringify(state)).toBe(before);
  });
});

// --------------------------------------------------------------------------- #
//  ledger_compaction.json — the compaction flow
// --------------------------------------------------------------------------- #

describe("compaction flow (SQLite fixture parity, scope sca)", () => {
  const fx = fixture("ledger_compaction");
  const ids = ["s1", "s2", "s3", "s4"] as const;
  const now = Date.parse(fx.now);

  function build(): { state: LedgerState; obsByScan: Record<string, Observation[]> } {
    const state = emptyState();
    const obsByScan: Record<string, Observation[]> = {};
    for (const key of ids) {
      const scan = fx.scans[key];
      const { observations } = persistFlatScan(state, scan.records, {
        scope: "sca",
        mode: "live",
        scanId: scan.id,
      });
      obsByScan[scan.id] = observations;
    }
    return { state, obsByScan };
  }

  const readPayload = (row: ScanRow) => {
    const key = ids.find((k) => fx.scans[k].id === row.scan_id);
    return key ? envelope(fx.scans[key].records) : null;
  };

  const counts = (obsByScan: Record<string, Observation[]>) =>
    Object.fromEntries(Object.entries(obsByScan).map(([id, obs]) => [id, obs.length]));

  it("dry run computes the exact preview", () => {
    const { state, obsByScan } = build();
    const plan = compactLedgerCore(state, fx.retention_days, null, readPayload, {
      dryRun: true,
      now,
      compactionId: "cmp-test",
      obsCountByScan: counts(obsByScan),
      archiveBytes: fx.expected.dry_run.archive_bytes_freed,
    });
    expectParity(plan.result, fx.expected.dry_run);
    expect(plan.state).toBeNull();
    expect(plan.compactionId).toBeNull();
    expect(plan.checkpoint!.version).toBe(CHECKPOINT_VERSION);
  });

  it("real run seals, converts episodes, and keeps the checkpoint faithful", () => {
    const { state, obsByScan } = build();
    const plan = compactLedgerCore(state, fx.retention_days, null, readPayload, {
      now,
      compactionId: "cmp-test",
      obsCountByScan: counts(obsByScan),
    });
    expectParity(
      Object.fromEntries(
        Object.entries(plan.result).filter(
          ([k]) => !["archive_bytes_freed", "db_bytes_freed"].includes(k),
        ),
      ),
      fx.expected.real,
    );

    const applied = plan.state!;
    const expected = fx.expected.after_compact;
    expectParity(scansAsc(applied.scans), shimScans(expected.scans));
    expectParity(applied.ledger, shimLedger(expected.ledger));
    expectParity(
      episodesWithoutId(applied.episodes as unknown as Record<string, unknown>[]),
      shimEpisodes(expected.episodes),
    );
    // Every sealed episode carries its scope out of the compaction (rule 6).
    for (const e of applied.episodes) {
      expect(e.scope).toBe("sca");
      expect(e.compaction_id).toBe("cmp-test");
      expect(e.finding_key.startsWith("sca:")).toBe(true);
    }

    // Checkpoint parity (keyed by finding_key; row order is storage-specific).
    expect(plan.checkpoint!.floor_scan_id).toBe(fx.expected.checkpoint.floor_scan_id);
    expect(plan.checkpoint!.floor_ts).toBe(fx.expected.checkpoint.floor_ts);
    expect(plan.checkpoint!.version).toBe(fx.expected.checkpoint.version);
    const cpByKey = Object.fromEntries(plan.checkpoint!.ledger.map((r) => [r.finding_key, r]));
    const expByKey = shimLedger(
      Object.fromEntries(fx.expected.checkpoint.ledger.map((r: any) => [r.vuln_key, r])),
    );
    expectParity(cpByKey, expByKey);
    for (const row of plan.checkpoint!.ledger) expect(row.scope).toBe("sca");

    // The scans the checkpoint seals keep their scope too.
    for (const r of plan.newly) expect(r.scope).toBe("sca");

    // Sealed scans refuse deletion, and the refusal names the scan id.
    expect(() =>
      deleteScansCore(applied, [fx.scans.s1.id], readPayload, plan.checkpoint),
    ).toThrow(SealedScanError);
    try {
      deleteScansCore(applied, [fx.scans.s1.id], readPayload, plan.checkpoint);
      expect.unreachable("expected SealedScanError");
    } catch (err) {
      expect((err as Error).message).toBe(fx.expected.sealed_delete_error);
      expect((err as Error).message).toContain(fx.scans.s1.id);
    }

    // Deleting a post-floor scan replays from the checkpoint.
    const del = deleteScansCore(applied, [fx.scans.s3.id], readPayload, plan.checkpoint, now);
    expectParity(del.result, fx.expected.delete_s3_result);
    const afterDel = fx.expected.after_delete_s3;
    expectParity(scansAsc(del.state.scans), shimScans(afterDel.scans));
    expectParity(del.state.ledger, shimLedger(afterDel.ledger));
    expectParity(
      episodesWithoutId(del.state.episodes as unknown as Record<string, unknown>[]),
      shimEpisodes(afterDel.episodes),
    );
    expectParity(obsTable(del.observationsByScan), shimObservations(afterDel.observations));
  });

  it("baseRows surfaces episodes with the (compacted) placeholder", () => {
    const { state, obsByScan } = build();
    const plan = compactLedgerCore(state, fx.retention_days, null, readPayload, {
      now,
      compactionId: "cmp-test",
      obsCountByScan: counts(obsByScan),
    });
    const rows = baseRows(plan.state!, { now });
    const compacted = rows.filter((r) => r.repo_name === "(compacted)");
    expect(compacted.map((r) => r.finding_key).sort()).toEqual(["sca:id:B", "sca:id:D"]);
    for (const r of compacted) {
      expect(r.status).toBe("RESOLVED");
      expect(r.mttr_days).not.toBeNull();
    }
  });

  it("a second compaction over the same state is a no-op (the cutoff is inside the seal)", () => {
    const { state, obsByScan } = build();
    const first = compactLedgerCore(state, fx.retention_days, null, readPayload, {
      now, compactionId: "cmp-1", obsCountByScan: counts(obsByScan),
    });
    const second = compactLedgerCore(first.state!, fx.retention_days, first.checkpoint, readPayload, {
      now, compactionId: "cmp-2", obsCountByScan: counts(obsByScan),
    });
    expect(second.result.no_op).toBe(true);
    expect(second.state).toBeNull();
    expect(second.checkpoint).toBeNull();
  });

  it("a newly-sealed scan with an unreadable archive refuses before any state change", () => {
    const { state, obsByScan } = build();
    const before = JSON.stringify(state);
    const blind = (row: ScanRow) => (row.scan_id === fx.scans.s1.id ? null : readPayload(row));
    expect(() =>
      compactLedgerCore(state, fx.retention_days, null, blind, {
        now, compactionId: "cmp-test", obsCountByScan: counts(obsByScan),
      }),
    ).toThrow(LedgerRebuildError);
    expect(JSON.stringify(state)).toBe(before);
  });

  it("a null retention window never compacts", () => {
    const { state } = build();
    const plan = compactLedgerCore(state, null, null, readPayload, {
      now, compactionId: "cmp-test",
    });
    expect(plan.result.no_op).toBe(true);
    expect(plan.result.scans_sealed).toBe(0);
  });
});

// --------------------------------------------------------------------------- #
//  Three scopes, one ledger — the behaviour gas/ has no golden for
