    severity: "HIGH", repo_id: "repo-1", repo_name: "acme/app", branch: "main",
    platform: "GITHUB", first_seen: "2026-01-01T00:00:00Z",
    last_seen: "2026-02-01T00:00:00Z", status: "RESOLVED",
    resolved_at: "2026-02-01T00:00:00Z", resolution_src: "api", reopened_count: 2,
    first_scan_id: "s1", last_scan_id: "s2", fix_date: "2026-01-15T00:00:00Z",
    fix_observed_at: "2026-01-16T00:00:00Z", fixed_version: "1.2.3", has_kev: true,
    has_exploit: false, epss: 0.42, risk_observed_at: "2026-01-16T00:00:00Z",
