describe("toEpisodeRow — the resolved_episodes column contract", () => {
  it("produces exactly TAB_HEADERS[TABS.episodes], no more and no less", () => {
    const row = toEpisodeRow(ledgerRowFixture(), "cmp-1");
    expect(Object.keys(row).sort()).toEqual([...TAB_HEADERS[TABS.episodes]!].sort());
  });

  it("carries scope, the classifier columns and the owner through the seal", () => {
    const row = toEpisodeRow(ledgerRowFixture(), "cmp-1");
    expect(row.scope).toBe("sca");
    expect(row.finding_key).toBe("sca:id:X");
    expect(row.identifier).toBe("CVE-X");
    expect(row.component).toBe("braces");
    expect(row.reopened_count).toBe(2);
    expect(row.compaction_id).toBe("cmp-1");
    expect(row.superseded_by_scan).toBeNull();
    expect(row.has_kev).toBe(true);
    expect(row.has_exploit).toBe(false);
    expect(row.epss).toBe(0.42);
    expect(row.cwe).toBe("CWE-79");
    expect(row.language).toBe("js");
    expect(row.owner_project).toBe("payments");
    expect(row.fix_date).toBe("2026-01-15T00:00:00Z");
    expect(row.fix_observed_at).toBe("2026-01-16T00:00:00Z");
  });

  it("keeps the tri-state: an unmeasured signal seals as null, never false", () => {
    const row = toEpisodeRow(
      ledgerRowFixture({ has_kev: null, has_exploit: null, epss: null }),
      "cmp-1",
    );
    expect(row.has_kev).toBeNull();
    expect(row.has_exploit).toBeNull();
    expect(row.epss).toBeNull();
  });

  it("a secrets lifecycle seals under its own scope", () => {
    const row = toEpisodeRow(
      ledgerRowFixture({ finding_key: "secrets:h:abc", scope: "secrets", identifier: "sd-1" }),
      "cmp-1",
    );
    expect(row.scope).toBe("secrets");
    expect(row.finding_key).toBe("secrets:h:abc");
  });
});

describe("compactionRow — the compactions tab column contract", () => {
  const plan = {
    result: {
      no_op: false, dry_run: false, scans_sealed: 2, episodes_created: 3,
      observations_pruned: 5, archive_bytes_freed: 615, db_bytes_freed: 0,
      floor_scan_id: "s2", floor_ts: "2026-01-08T06:00:00Z",
    },
    checkpoint: null,
    newly: [],
    state: null,
    compactionId: "cmp-1",
  };

  it("produces exactly TAB_HEADERS[TABS.compactions]", () => {
    const row = compactionRow(plan, "drive-cp-1", Date.parse("2026-07-01T00:00:00Z"));
    expect(Object.keys(row).sort()).toEqual([...TAB_HEADERS[TABS.compactions]!].sort());
    expect(row.compaction_id).toBe("cmp-1");
    expect(row.checkpoint_ref).toBe("drive-cp-1");
    expect(row.scans_sealed).toBe(2);
    expect(row.episodes_created).toBe(3);
    expect(row.archive_bytes_freed).toBe(615);
    expect(row.ts).toBe("2026-07-01T00:00:00Z");
  });

  /**
   * THE DIVERGENCE, PINNED. gas/'s compactions tab has ten columns; this one has eight. The
   * two counters live on CompactionResult (a caller can surface them) and have nowhere to be
   * written, and sheetsDb maps by header NAME — so emitting them would produce keys silently
   * dropped on the way to the sheet, which reads as data captured when it is data lost.
   */
  it("omits the two counters the tab has no columns for", () => {
    const row = compactionRow(plan, null);
    expect("observations_pruned" in row).toBe(false);
    expect("db_bytes_freed" in row).toBe(false);
    expect(TAB_HEADERS[TABS.compactions]).not.toContain("observations_pruned");
    expect(TAB_HEADERS[TABS.compactions]).not.toContain("db_bytes_freed");
  });
});

describe("settledEpisodeRows", () => {
  const cpRow = ledgerRowFixture({ status: "RESOLVED", last_scan_id: "s2" });

  it("takes a checkpoint-RESOLVED row whose live state is untouched post-floor", () => {
    const live = { ...cpRow };
    const out = settledEpisodeRows([cpRow], { [cpRow.finding_key]: live }, new Set(["s2"]));
    expect(out).toEqual([live]);
  });

  it("skips a row the live ledger reopened, re-dated, or re-saw after the floor", () => {
    const key = cpRow.finding_key;
    const sealed = new Set(["s2"]);
    expect(settledEpisodeRows([cpRow], {}, sealed)).toEqual([]);
    expect(
      settledEpisodeRows([cpRow], { [key]: { ...cpRow, status: "OPEN" } }, sealed),
    ).toEqual([]);
    expect(
      settledEpisodeRows(
        [cpRow], { [key]: { ...cpRow, resolved_at: "2026-03-01T00:00:00Z" } }, sealed,
      ),
    ).toEqual([]);
    expect(
      settledEpisodeRows([cpRow], { [key]: { ...cpRow, last_scan_id: "s3" } }, sealed),
    ).toEqual([]);
    // A checkpoint row that was never resolved is not an episode at all.
    expect(
      settledEpisodeRows(
        [{ ...cpRow, status: "OPEN" }], { [key]: { ...cpRow } }, sealed,
      ),
    ).toEqual([]);
  });
});

describe("loadReplayPayloads", () => {
  const scan = (over: Partial<ScanRow>): ScanRow => ({
    scan_id: "s1", ts: "2026-01-01T00:00:00Z", scope: "sca", mode: "live",
    severities: null, total: 0, new_count: 0, resolved_count: 0, reopened_count: 0,
    raw_ref: null, obs_ref: null, sealed: 0, ...over,
  });

  it("skips sealed rows and never reads their archives", () => {
    const read = (r: ScanRow) => {
      if (r.sealed) throw new Error("sealed archives must not be read");
      return envelope([]);
    };
    const out = loadReplayPayloads(
      [scan({ scan_id: "a", sealed: 1 }), scan({ scan_id: "b" })],
      read,
      (id) => id,
    );
    expect(out.map((i) => i.row.scan_id)).toEqual(["b"]);
  });

  /**
   * DIVERGENCE (gas/), pinned. gas/ guarded this throw with `shape === "flat"`, because a
   * grouped scan never touched the ledger. There is no grouped shape here, so EVERY unsealed
   * scan is load-bearing and a missing archive is fatal for any of them.
   */
  it("throws LedgerRebuildError naming the scan when an unsealed archive is missing", () => {
    expect(() =>
      loadReplayPayloads([scan({ scan_id: "b" })], () => null, (id) => `gone: ${id}`),
    ).toThrow(new LedgerRebuildError("gone: b"));
  });
});

describe("recordsFromPayload", () => {
  const recs = [{ id: "A" }, { id: "B" }];

  it("unwraps every envelope shape the archive can hold", () => {
    expect(recordsFromPayload({ data: { libraryVulnerabilities: { nodes: recs } } })).toEqual(recs);
    expect(recordsFromPayload({ data: { sastFindings: { nodes: recs } } })).toEqual(recs);
    expect(recordsFromPayload({ data: { secretInstances: { nodes: recs } } })).toEqual(recs);
    expect(recordsFromPayload({ nodes: recs })).toEqual(recs);
    expect(recordsFromPayload(recs)).toEqual(recs);
    expect(recordsFromPayload(JSON.stringify({ nodes: recs }))).toEqual(recs);
  });

  it("merges a list of page envelopes", () => {
    expect(
      recordsFromPayload([
        { data: { secretInstances: { nodes: [recs[0]] } } },
        { data: { secretInstances: { nodes: [recs[1]] } } },
      ]),
    ).toEqual(recs);
  });

  it("an absent or empty payload is an empty record list, never a throw", () => {
    expect(recordsFromPayload(null)).toEqual([]);
    expect(recordsFromPayload(undefined)).toEqual([]);
    expect(recordsFromPayload([])).toEqual([]);
    expect(recordsFromPayload({ nodes: null })).toEqual([]);
  });
});

describe("cutoffMs / isAfter — the retention boundary", () => {
  const now = Date.parse("2026-07-01T00:00:00Z");

  it("cutoffMs subtracts the window and never less than RETENTION_MIN_DAYS", () => {
    expect(RETENTION_MIN_DAYS).toBe(30);
    expect(cutoffMs(now, 180)).toBe(now - 180 * 86_400_000);
    expect(cutoffMs(now, 30)).toBe(now - 30 * 86_400_000);
    // Below the floor, and at zero / negative, the floor wins.
    expect(cutoffMs(now, 1)).toBe(now - 30 * 86_400_000);
    expect(cutoffMs(now, 0)).toBe(now - 30 * 86_400_000);
    expect(cutoffMs(now, -5)).toBe(now - 30 * 86_400_000);
  });

  it("isAfter is strict, and an unparseable or absent ts is never after", () => {
    const cutoff = cutoffMs(now, 30); // 2026-06-01T00:00:00Z
    expect(isAfter("2026-06-01T00:00:01Z", cutoff)).toBe(true);
    expect(isAfter("2026-06-01T00:00:00Z", cutoff)).toBe(false); // the boundary itself
    expect(isAfter("2026-05-31T23:59:59Z", cutoff)).toBe(false);
    expect(isAfter(null, cutoff)).toBe(false);
    expect(isAfter("not-a-date", cutoff)).toBe(false);
  });
});

describe("deleteScansCore seeded from a checkpoint", () => {
  it("seeds the rebuilt ledger from the checkpoint, minus keys already sealed as episodes", () => {
    const sealedKey = "sca:id:SEALED";
    const liveKey = "sca:id:LIVE";
    const checkpoint: Checkpoint = {
      version: CHECKPOINT_VERSION,
      floor_scan_id: "s1",
      floor_ts: "2026-01-01T00:00:00Z",
      ledger: [
        ledgerRowFixture({ finding_key: sealedKey }),
        ledgerRowFixture({ finding_key: liveKey, status: "OPEN", resolved_at: null }),
      ],
    };
    const state: LedgerState = {
      scans: [
        {
          scan_id: "s1", ts: "2026-01-01T00:00:00Z", scope: "sca", mode: "live",
          severities: null, total: 1, new_count: 1, resolved_count: 0, reopened_count: 0,
          raw_ref: null, obs_ref: null, sealed: 1,
        },
        {
          scan_id: "s2", ts: "2026-02-01T00:00:00Z", scope: "sca", mode: "live",
          severities: null, total: 0, new_count: 0, resolved_count: 0, reopened_count: 0,
          raw_ref: null, obs_ref: null, sealed: 0,
        },
      ],
      ledger: {},
      episodes: [toEpisodeRow(ledgerRowFixture({ finding_key: sealedKey }), "cmp-1")],
    };
    // Deleting the only unsealed scan leaves nothing to replay; the checkpoint is the state.
    const del = deleteScansCore(state, ["s2"], () => envelope([]), checkpoint);
    expect(Object.keys(del.state.ledger)).toEqual([liveKey]);
    expect(del.state.scans.map((r) => r.scan_id)).toEqual(["s1"]);
    expect(del.state.episodes.map((e) => e.finding_key)).toEqual([sealedKey]);
    // Supersessions reset — a post-floor survivor re-derives them during replay.
    expect(del.state.episodes.every((e) => e.superseded_by_scan === null)).toBe(true);
    expect(del.result).toEqual({ deleted: 1, scans: 1, tracked: 2 });
  });
});
